import{_ as t,o as r,c as a,a6 as n}from"./chunks/framework.B_q3ZJNF.js";const m=JSON.parse('{"title":"与真实产品的差异清单","description":"","frontmatter":{"title":"与真实产品的差异清单"},"headers":[],"relativePath":"immersive-translate-course/divergence.md","filePath":"immersive-translate-course/docs/divergence.md"}'),i={name:"immersive-translate-course/divergence.md"};function o(s,e,l,c,d,p){return r(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="与真实产品的差异清单" tabindex="-1">与真实产品的差异清单 <a class="header-anchor" href="#与真实产品的差异清单" aria-label="Permalink to &quot;与真实产品的差异清单&quot;">​</a></h1><p>全书每一处「本课程简化为…」的集中登记——不是歉疚，是路线图：每一条都标了来源章，顺着清单就能把教学引擎长成真实产品。共 8 组。</p><h2 id="按登记顺序" tabindex="-1">按登记顺序 <a class="header-anchor" href="#按登记顺序" aria-label="Permalink to &quot;按登记顺序&quot;">​</a></h2><ul><li><strong>09 章 → 差异清单</strong>：壳的边界四条：①无开关无 popup，上页即跑且每个 http/https 页面都注入（真实产品有快捷键与按站点开关）②mainContentOnly 的闸装了没拉，壳走全页翻，侧栏标签也进账 ③译文是裸 p，无浅色/字号等样式注入 ④产物更新不热替换，需 chrome://extensions 重载＋刷新页面</li><li><strong>08 章 → 差异清单</strong>：动态适配边界五条：已翻译子树被移动会重发一单（幂等渲染兜底，缓存档白送）；只监听 childList——原地改文本/改属性不触发增量；往已有段落新塞内联内容不重翻（增量以块上树为记账单位）；环境无 MutationObserver 时静默退化为静态引擎；mainContentOnly 只约束开机整页路径，动态追加进非正文区的块照样翻译</li><li><strong>03 章 → 差异清单</strong>：译文统一用 p 插在原文正后方，li 的译文落在列表项外（ul 内容模型已知名偏差，浏览器照常渲染）</li><li><strong>05 章 → 差异清单</strong>：占位标记登记两条：嵌套内联（a 套 strong、隔层包裹）按纯文本摊平不保结构；真实服务对 ⟦⟧ 记号存活无承诺，被吞走降级（格式丢、译文留）</li><li><strong>06 章 → 差异清单</strong>：主内容启发式边界三条：正文整个住在链接里的版面（目录/摘要/书签站）会认反（demo 实证）；多文章列表页只挑分量最大的一篇；地标缺席时份额线可能收得偏紧、漏掉引言</li><li><strong>02 章 → 差异清单</strong>：差异清单登记两条近似偏差：display 被作者改过的元素误判；清单未收录标签按内联处理</li><li><strong>07 章 → 差异清单</strong>：批量缓存档边界五条：缓存无过期无容量上限；429 只防不治（无重试退避）；批量档降级粒度是整单（一块失败同单连坐）；CHAR_BUDGET=200 教学手感值，真实服务单请求配额以文档为准；缓存认句不认翻译器，换翻译器需清缓存</li><li><strong>04 章 → 差异清单</strong>：接真实翻译 API 的差异（密钥、计费、流式）登记进差异清单附录</li></ul><h2 id="怎么用这份清单" tabindex="-1">怎么用这份清单 <a class="header-anchor" href="#怎么用这份清单" aria-label="Permalink to &quot;怎么用这份清单&quot;">​</a></h2><p>把它当接真实服务的作业清单：第 ①④⑤ 组是「接真 API」的第一站（密钥、计费、限流退避），第 ③⑧ 组是产品化（开关、样式注入），其余是启发式与格式的边角。每一条在来源章都有机制层的成因解释——为什么简化、简化掉了什么、什么场景会咬人。</p>',6)])])}const _=t(i,[["render",o]]);export{m as __pageData,_ as default};
